/**
 * `POST /run/step`.
 */
export interface StepRequest {
  /**
   * Ticks to run, `1..=1000000`.
   * @minimum 0
   */
  count: number;
}

/**
 * The answer of `POST /run/step`.
 */
export interface StepResult {
  /** Whether all of them ran; false when the duration or a `stop` ended the run first. */
  completed: boolean;
  /**
   * The tick reached.
   * @minimum 0
   */
  reached: number;
  /**
   * The ticks asked for.
   * @minimum 0
   */
  requested: number;
  /** The run status after the step. */
  run: RunStatus;
  /** The state hash at `reached`: 16 lower-case hex digits. */
  state_hash: string;
  /** The simulation time reached, in seconds. */
  time_s: number;
}

/**
 * Why a run is `stopped`.
 */
export type StopReason = typeof StopReason[keyof typeof StopReason];


// eslint-disable-next-line @typescript-eslint/no-redeclare
export const StopReason = {
  command: 'command',
  duration: 'duration',
  plugin_fault: 'plugin_fault',
  error: 'error',
  network_fault: 'network_fault',
} as const;

/**
 * A problem with a client message; the connection stays open.
 */
export interface StreamError {
  /** The stable code. */
  code: StreamErrorCode;
  /** A message for a person. */
  message: string;
}

/**
 * Stable codes of stream `error` messages.
 */
export type StreamErrorCode = typeof StreamErrorCode[keyof typeof StreamErrorCode];


// eslint-disable-next-line @typescript-eslint/no-redeclare
export const StreamErrorCode = {
  invalid_message: 'invalid_message',
  unknown_message_type: 'unknown_message_type',
  invalid_subscription: 'invalid_subscription',
} as const;

export type StreamFilterBbox = GeoBox | null;

/**
 * Only these entities, at most 10,000.
 */
export type StreamFilterEntityIds = number[] | null;

/**
 * Only events of these kinds.
 */
export type StreamFilterEventKinds = string[] | null;

/**
 * What a client may ask the stream for.
 */
export interface StreamFilter {
  bbox?: StreamFilterBbox;
  /** Only these entities, at most 10,000. */
  entity_ids?: StreamFilterEntityIds;
  /** Only events of these kinds. */
  event_kinds?: StreamFilterEventKinds;
}

/**
 * Any stream message; the root of `api/stream.schema.json`.
 */
export type StreamMessage = ClientMessage | ServerMessage;

/**
 * The stream settings in force, reported by `hello`.
 */
export interface StreamSettings {
  /** The rate used when `subscribe` gives none. */
  default_rate_hz: number;
  /**
   * The most `entity_ids` in one subscription.
   * @minimum 0
   */
  max_entity_ids: number;
  /**
   * Events per frame before `events_truncated` is set.
   * @minimum 0
   */
  max_events_per_frame: number;
  /**
   * The longest accepted client message (1009 beyond it).
   * @minimum 0
   */
  max_message_bytes: number;
  /** The highest rate a subscription may ask for. */
  max_rate_hz: number;
  /**
   * Frames queued per connection before the oldest is dropped.
   * @minimum 0
   */
  queue_frames: number;
  /** A send that takes longer ends the connection: close code 1008 `too_slow` when the close frame
can still be delivered, otherwise the connection is dropped. */
  send_timeout_s: number;
}

export type SubscriptionFilter = StreamFilter | null;

/**
 * The most frames per second, in `(0, 60]`; default 30.
 */
export type SubscriptionMaxRateHz = number | null;

/**
 * Whether frames carry `state_hash`; default false.
 */
export type SubscriptionStateHash = boolean | null;

/**
 * The body of a `subscribe` message; a new one replaces the previous one. Unknown fields are
refused.
 */
export interface Subscription {
  filter?: SubscriptionFilter;
  /** The most frames per second, in `(0, 60]`; default 30. */
  max_rate_hz?: SubscriptionMaxRateHz;
  /** Whether frames carry `state_hash`; default false. */
  state_hash?: SubscriptionStateHash;
}

