type AwaitedInput<T> = PromiseLike<T> | T;

      type Awaited<O> = O extends AwaitedInput<infer T> ? T : never;


type SecondParameter<T extends (...args: never) => unknown> = Parameters<T>[1];



/**
 * @summary Validates a behavior graph document without changing any state. A `name` that is absolute or
contains `..` is refused with `422 validation_failed`. Inside a loaded scenario the
document sees the session's plugins and graphs; otherwise only the engine's own. The
diagnostics are the result: an invalid document answers 200 with `valid: false`.
 */
export const getValidateBehaviorUrl = () => {


  

  return `/api/v1/behaviors/validate`
}

export const validateBehavior = async (validateGraphRequest: ValidateGraphRequest, options?: RequestInit): Promise<ValidationResult> => {
  
  return engineFetch<ValidationResult>(getValidateBehaviorUrl(),
  {      
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      validateGraphRequest,)
  }
);}




export const getValidateBehaviorMutationOptions = <TError = ErrorType<Problem>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof validateBehavior>>, TError,{data: BodyType<ValidateGraphRequest>}, TContext>, request?: SecondParameter<typeof engineFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof validateBehavior>>, TError,{data: BodyType<ValidateGraphRequest>}, TContext> => {

const mutationKey = ['validateBehavior'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};

      


      const mutationFn: MutationFunction<Awaited<ReturnType<typeof validateBehavior>>, {data: BodyType<ValidateGraphRequest>}> = (props) => {
          const {data} = props ?? {};

          return  validateBehavior(data,requestOptions)
        }

        


  return  { mutationFn, ...mutationOptions }}

    export type ValidateBehaviorMutationResult = NonNullable<Awaited<ReturnType<typeof validateBehavior>>>
    export type ValidateBehaviorMutationBody = BodyType<ValidateGraphRequest>
    export type ValidateBehaviorMutationError = ErrorType<Problem>

    /**
 * @summary Validates a behavior graph document without changing any state. A `name` that is absolute or
contains `..` is refused with `422 validation_failed`. Inside a loaded scenario the
document sees the session's plugins and graphs; otherwise only the engine's own. The
diagnostics are the result: an invalid document answers 200 with `valid: false`.
 */
export const useValidateBehavior = <TError = ErrorType<Problem>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof validateBehavior>>, TError,{data: BodyType<ValidateGraphRequest>}, TContext>, request?: SecondParameter<typeof engineFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof validateBehavior>>,
        TError,
        {data: BodyType<ValidateGraphRequest>},
        TContext
      > => {

      const mutationOptions = getValidateBehaviorMutationOptions(options);

      return useMutation(mutationOptions, queryClient);
    }
    
