/**
 * @summary The registered components, optionally of one kind. With a scenario the list includes the
plugins' components and the scenario's behavior graphs; without one, the engine's own.
 */
export const getListComponentsUrl = (params?: ListComponentsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/components?${stringifiedParams}` : `/api/v1/components`
}

